export function toScreen(
  range: number,
  bearing: number,
  heading: number,
  pxPerM: number,
  out: { x: number; y: number },
): { x: number; y: number } {
  const a = bearing - heading
  const r = range * pxPerM
  out.x = Math.sin(a) * r
  out.y = -Math.cos(a) * r
  return out
}

