  const daysToFull = (((0.5 - cycle) % 1) + 1) % 1 * SYNODIC_DAYS
  const daysToNew = (((1 - cycle) % 1) + 1) % 1 * SYNODIC_DAYS
  return { ageDays, illumination, cycle, waxing, daysToFull, daysToNew, name: phaseName(cycle) }
}

